function exampleScores(directedTotals) {
  const selectedQuestions = questionsForMode('quick', 'en', 2);
  const answers = selectedQuestions.map((question, index) => {
    const total = directedTotals[axes.findIndex(axis => axis.id === question.axis)];
    const precedingCount = selectedQuestions.slice(0, index).filter(statement => statement.axis === question.axis).length;
    const contribution = Math.sign(total) * Math.min(2, Math.max(0, Math.abs(total) - precedingCount * 2));
    return contribution * question.direction;
  });
  return calculateScores(selectedQuestions, answers);
}

