function previewCard(profile, index) {
  const shortLabels = ['Equality', 'Liberty', 'Democracy', 'Cooperation', 'Diplomacy', 'Openness', 'Progress', 'Secularism', 'Ecology', 'Rehabilitation', 'Local power', 'Precaution'];
  return `<article class="preview-card preview-${profile.color} ${index === 0 ? 'is-current' : index === 1 ? 'is-after' : 'is-before'}" data-preview-card="${index}" aria-hidden="${index !== 0}"><div class="preview-brand"><span><b>12</b> axes</span><i></i><small>EXAMPLE RESULT</small></div><p class="preview-category">48 QUESTIONS · QUESTIONNAIRE V2</p><h2>${profile.name}</h2><div class="preview-body"><div class="preview-radar">${radarChart(profile.scores, { demo: true })}</div><div class="preview-scores"><span class="preview-label">FIRST-POLE SCORES · OPPOSITE = 100 − SCORE</span>${shortLabels.map((label, axisIndex) => `<div><i style="background:${axes[axisIndex].color}">${String(axisIndex + 1).padStart(2, '0')}</i><span>${label}</span><b style="color:${axes[axisIndex].color}"><em style="width:${profile.scores[axisIndex]}%;background:${axes[axisIndex].color}"></em></b><small>${profile.scores[axisIndex]}%</small></div>`).join('')}</div></div><div class="preview-details"><div><span class="preview-label">SEVERAL LEANS, NO IDENTITY LABEL</span>${profile.highlights.map(axisIndex => `<p>${profile.scores[axisIndex] >= 50 ? axes[axisIndex].left : axes[axisIndex].right}<b>${Math.max(profile.scores[axisIndex], 100 - profile.scores[axisIndex])}%</b></p>`).join('')}</div><div><span class="preview-label">HOW THIS EXAMPLE WAS MADE</span><p>Synthetic answers, real scoring.</p><p>Not a person or a measured group.</p></div></div><div class="preview-card-footer"><span>ILLUSTRATION · NOT YOUR RESULT</span><b>12 AXES</b></div></article>`;
}

function axisCards() {
  return axes.map((axis, index) => `<a class="axis-row" href="/axes#${axis.id}"><div class="axis-card-title"><span class="axis-number">${String(index + 1).padStart(2, '0')}</span><h3>${axis.name}</h3></div><div class="axis-poles">${interfaceIcon(['scale', 'shield', 'person', 'globe', 'shield', 'globe', 'spark', 'book', 'globe', 'scale', 'chart', 'spark'][index])}<strong>${axis.left}</strong><span>↔</span><strong>${axis.right}</strong></div><p>${axis.description}</p></a>`).join('');
}

